// Hand-written `axios` stub, in the real library's shape: the default export is
// an `AxiosStatic`, `create` hands back an `AxiosInstance`, and both keep their
// options under `defaults`.

export interface AxiosResponse<Data = unknown> {
  data: Data;
  status: number;
}

export interface AxiosRequestConfig {
  baseURL?: string;
  method?: string;
  data?: unknown;
  headers?: Record<string, string>;
  params?: Record<string, unknown>;
}

export interface AxiosInstance {
  (url: string, config?: AxiosRequestConfig): Promise<AxiosResponse>;
  defaults: AxiosRequestConfig;
  get<Data = unknown>(url: string, config?: AxiosRequestConfig): Promise<AxiosResponse<Data>>;
  post<Data = unknown>(url: string, body?: unknown, config?: AxiosRequestConfig): Promise<AxiosResponse<Data>>;
  patch<Data = unknown>(url: string, body?: unknown, config?: AxiosRequestConfig): Promise<AxiosResponse<Data>>;
  delete<Data = unknown>(url: string, config?: AxiosRequestConfig): Promise<AxiosResponse<Data>>;
}

export interface AxiosStatic extends AxiosInstance {
  create(config?: AxiosRequestConfig): AxiosInstance;
}

declare const axios: AxiosStatic;
export default axios;
